const wh = $('Webhook').first().json.body;
let html = $input.first().json.data ?? '';

// Extraction du texte brut
html = html.replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '');
html = html.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '');
html = html.replace(/<[^>]+>/g, ' ');
html = html.replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&');
html = html.replace(/\s+/g, ' ').trim().slice(0, 5000);

const isFacebook = (wh.url ?? '').includes('facebook.com') || (wh.url ?? '').includes('fb.com');
const pageText = html || '[Page inaccessible ou vide]';
const sourceType = isFacebook ? 'Page Facebook uniquement (pas de site web propre)' : 'Site web';
const needTypes = (wh.needType ?? []).join(', ') || 'non précisé';
const company = wh.company || wh.name || 'inconnue';

const prompt = [
  'Tu analyses une entreprise prospect pour DeepShift (Pierre Connes — création de web apps sur mesure et consulting digital).',
  '',
  'Entreprise : ' + company,
  'URL analysée : ' + wh.url,
  'Type de présence : ' + sourceType,
  'Besoins pressentis : ' + needTypes,
  '',
  'Contenu de leur présence en ligne :',
  '---',
  pageText,
  '---',
  '',
  'Analyse et réponds UNIQUEMENT en JSON valide (pas de texte autour) :',
  '{',
  '  "summary": "2-3 phrases : secteur activité, taille estimée, maturité digitale actuelle",',
  '  "opportunities": ["opportunité concrète 1 pour DeepShift", "opportunité 2"],',
  '  "digital_maturity": "faible | moyenne | élevée",',
  '  "score": 7,',
  '  "score_reason": "raison du score en 1 phrase concise"',
  '}'
].join('\n');

return [{
  json: {
    prospectId: wh.prospectId,
    claudeBody: JSON.stringify({
      model: 'claude-haiku-4-5-20251001',
      max_tokens: 600,
      messages: [{ role: 'user', content: prompt }]
    })
  }
}];

const prev = $('Build Claude Request').first().json;
const rawText = $input.first().json.content?.[0]?.text ?? '{}';

let parsed = {};
try {
  const match = rawText.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match?.[0] ?? '{}');
} catch (e) {
  parsed = {};
}

const parts = [];
if (parsed.summary) parts.push(parsed.summary);
if (parsed.opportunities?.length) {
  parts.push('Opportunités : ' + parsed.opportunities.join(' · '));
}
if (parsed.digital_maturity) {
  parts.push('Maturité digitale : ' + parsed.digital_maturity);
}

return [{
  json: {
    prospectId: prev.prospectId,
    aiSummary: parts.join('\n') || 'Analyse non disponible',
    aiScoreReason: parsed.score_reason ?? null,
    score: parsed.score ?? null,
  }
}];
